#!/usr/bin/env python3
"""IDB-free disassembly / pointer inspection for editor.exe or fm.exe.

Purpose: give b39 branch-level static evidence (L3) without touching any IDA
database (``ida/*.i64`` is exclusively locked by a parallel session).

Everything is read-only: the PE is opened with pefile, code bytes are pulled by
RVA, and capstone linear-disassembles an unwind-table function range.

Sub-commands
    func  <VA> [...]        linear disassemble whole unwind function(s)
    thunk <VA> [...]        show the first instructions at a VA (jump thunks)
    ptr   <VA> [...]        read 8-byte little-endian values stored at a VA
    str   <text> [...]      find ASCII and UTF-16LE occurrences of a text
    refs  <VA> [...]        every 32-bit RIP-relative reference resolving to VA
    iat   <dll:name> [...]  IAT slot address(es) for imports, plus call sites

Usage examples
    python -I scripts/editor_pe_disasm.py --pe input/editor.exe func 0x141430CE0
    python -I scripts/editor_pe_disasm.py --pe input/editor.exe refs 0x141431690
    python -I scripts/editor_pe_disasm.py --pe input/editor.exe iat KERNEL32.dll:FindFirstFileExW

Exit codes: 0 = ok, 2 = usage / input error.
"""
from __future__ import annotations

import argparse
import bisect
import json
import struct
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
if hasattr(sys.stdout, "reconfigure"):
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")

import capstone
import pefile

MD = capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_64)
MD.detail = True


class PE:
    def __init__(self, path: Path):
        self.path = path
        self.data = path.read_bytes()
        self.pe = pefile.PE(str(path), fast_load=True)
        self.base = self.pe.OPTIONAL_HEADER.ImageBase
        self.sections = []
        for s in self.pe.sections:
            self.sections.append({
                "name": s.Name.rstrip(b"\0").decode("latin1"),
                "va": s.VirtualAddress,
                "vsize": s.Misc_VirtualSize,
                "raw": s.PointerToRawData,
                "rawsize": s.SizeOfRawData,
                "chars": s.Characteristics,
            })
        d = self.pe.OPTIONAL_HEADER.DATA_DIRECTORY[3]
        self.unwind = sorted(struct.iter_unpack("<III", self.pe.get_data(d.VirtualAddress, d.Size)))
        self.unwind_starts = [r[0] for r in self.unwind]

    # --- address translation -------------------------------------------------
    def off(self, va: int) -> int | None:
        rva = va - self.base
        for s in self.sections:
            if s["va"] <= rva < s["va"] + max(s["vsize"], s["rawsize"]):
                delta = rva - s["va"]
                if delta < s["rawsize"]:
                    return s["raw"] + delta
                return None
        return None

    def va_of(self, off: int) -> int | None:
        for s in self.sections:
            if s["raw"] <= off < s["raw"] + s["rawsize"]:
                return self.base + s["va"] + (off - s["raw"])
        return None

    def section_of(self, va: int) -> str:
        rva = va - self.base
        for s in self.sections:
            if s["va"] <= rva < s["va"] + max(s["vsize"], s["rawsize"]):
                return s["name"]
        return "?"

    def func(self, va: int):
        """(start, end) of the unwind record covering va, else None."""
        rva = va - self.base
        i = bisect.bisect_right(self.unwind_starts, rva) - 1
        if i >= 0:
            rec = self.unwind[i]
            if rec[0] <= rva < rec[1]:
                return self.base + rec[0], self.base + rec[1]
        return None

    def code(self, va: int, size: int) -> bytes:
        o = self.off(va)
        if o is None:
            raise ValueError(f"VA {va:#x} not backed by file data")
        return self.data[o:o + size]

    def qword(self, va: int) -> int:
        return struct.unpack_from("<Q", self.code(va, 8))[0]

    def dword(self, va: int) -> int:
        return struct.unpack_from("<I", self.code(va, 4))[0]

    def ascii_at(self, va: int, limit: int = 200) -> str:
        o = self.off(va)
        if o is None:
            return ""
        chunk = self.data[o:o + limit]
        out = bytearray()
        for b in chunk:
            if 32 <= b < 127:
                out.append(b)
            else:
                break
        return out.decode("ascii", "replace")


def disasm(pe: PE, start: int, end: int, limit: int = 4000) -> list[dict]:
    rows = []
    code = pe.code(start, end - start)
    for insn in MD.disasm(code, start):
        if insn.address >= end:
            break
        note = ""
        # RIP-relative memory operand -> annotate absolute VA + string preview
        for op in insn.operands:
            if op.type == capstone.x86.X86_OP_MEM and op.mem.base == capstone.x86.X86_REG_RIP:
                target = insn.address + insn.size + op.mem.disp
                note += f" ; [rip+{op.mem.disp:#x}] -> {target:#x} {pe.section_of(target)}"
                text = pe.ascii_at(target, 60)
                if len(text) >= 4:
                    note += f' "{text}"'
            elif op.type == capstone.x86.X86_OP_IMM and insn.mnemonic.startswith(("call", "j")):
                note += f" -> {op.imm:#x}"
        rows.append({"va": f"{insn.address:#x}", "bytes": insn.bytes.hex(),
                     "text": f"{insn.mnemonic} {insn.op_str}".strip(), "note": note.strip()})
        if len(rows) >= limit:
            rows.append({"va": "-", "bytes": "", "text": "... truncated ...", "note": ""})
            break
    return rows


def cmd_func(pe: PE, args) -> int:
    out = {}
    for text in args:
        va = int(text, 16)
        span = pe.func(va)
        if span is None:
            print(f"{text}: no unwind record covers this VA", file=sys.stderr)
            continue
        start, end = span
        rows = disasm(pe, start, end)
        print(f"=== {start:#x}..{end:#x}  ({end - start} bytes, {len(rows)} insns) ===")
        for r in rows:
            print(f"{r['va']:>12}  {r['bytes']:<24} {r['text']:<46} {r['note']}")
        out[text] = {"start": f"{start:#x}", "end": f"{end:#x}", "rows": rows}
    if args_json:
        Path(args_json).write_text(json.dumps(out, indent=1), encoding="utf8")
    return 0


def cmd_thunk(pe: PE, args) -> int:
    for text in args:
        va = int(text, 16)
        rows = disasm(pe, va, va + 32, limit=8)
        print(f"=== {va:#x} ({pe.section_of(va)}) ===")
        for r in rows:
            print(f"{r['va']:>12}  {r['bytes']:<24} {r['text']:<46} {r['note']}")
    return 0


def cmd_ptr(pe: PE, args) -> int:
    for text in args:
        va = int(text, 16)
        targets = [pe.qword(va + 8 * i) for i in range(2)]
        print(f"{va:#x} ({pe.section_of(va)}): " + ", ".join(f"{t:#x}" for t in targets))
        for t in targets:
            if t > pe.base:
                print(f"    {t:#x} {pe.section_of(t)}  {pe.ascii_at(t, 40)!r}")
    return 0


def cmd_str(pe: PE, args) -> int:
    for text in args:
        for encoding, needle in (("ascii", text.encode()), ("utf16", text.encode("utf-16-le"))):
            pos = 0
            hits = []
            while True:
                pos = pe.data.find(needle, pos)
                if pos < 0:
                    break
                va = pe.va_of(pos)
                if va is not None:
                    hits.append(va)
                pos += 1
            print(f"{text!r} [{encoding}] {len(hits)} hit(s): " + ", ".join(f"{h:#x}" for h in hits[:20]))
    return 0


def cmd_refs(pe: PE, args) -> int:
    import numpy as np
    findings = {}
    targets = [int(a, 16) for a in args]
    for s in pe.sections:
        if not (s["chars"] & 0x20000000):
            continue
        raw, rawsize, sva = s["raw"], s["rawsize"], s["va"]
        if rawsize == 0:
            continue
        # displacement at byte offset (4*i + phase); assumed to end the instruction,
        # so target = base + sva + 4*i + phase + 4 + disp.
        for phase in range(4):
            n = (rawsize - phase) // 4

[73 more lines in file. Use offset=221 to continue.]

        if rawsize == 0:
            continue
        # displacement at byte offset (4*i + phase); assumed to end the instruction,
        # so target = base + sva + 4*i + phase + 4 + disp.
        for phase in range(4):
            n = (rawsize - phase) // 4
            if n <= 0:
                continue
            vals = np.frombuffer(pe.data, dtype="<i4", count=n, offset=raw + phase).astype(np.int64)
            resolved = vals + np.int64(pe.base + sva + phase + 4) + 4 * np.arange(n, dtype=np.int64)
            for t in targets:
                idx = np.flatnonzero(resolved == t)
                for i in idx:
                    ref_va = pe.base + sva + 4 * int(i) + phase
                    findings.setdefault(f"{t:#x}", []).append({
                        "ref_at": f"{ref_va:#x}", "instruction_end": f"{ref_va + 4:#x}",
                        "section": s["name"],
                    })
    for t in targets:
        rows = findings.get(f"{t:#x}", [])
        print(f"{t:#x}: {len(rows)} rip-relative reference(s)")
        for r in rows[:40]:
            start = pe.func(int(r["instruction_end"], 16))
            owner = f"{start[0]:#x}" if start else "?"
            print(f"    at {r['ref_at']} (ends {r['instruction_end']}) fn {owner} [{r['section']}]")
    return 0


def cmd_iat(pe: PE, args) -> int:
    pe.pe.parse_data_directories(directories=[1])
    want = {}
    for text in args:
        dll, _, name = text.partition(":")
        want.setdefault(dll.lower(), set()).add(name)
    for entry in getattr(pe.pe, "DIRECTORY_ENTRY_IMPORT", []):
        dll = entry.dll.decode()
        if dll.lower() not in want:
            continue
        for imp in entry.imports:
            nm = imp.name.decode() if imp.name else f"#{imp.ordinal}"
            if nm.lower() in {n.lower() for n in want[dll.lower()]}:
                print(f"{dll}!{nm}: IAT slot {imp.address:#x}")
    return 0


def main() -> int:
    global args_json
    args_json = None
    ap = argparse.ArgumentParser(description="IDB-free disassembly helper (read-only)")
    ap.add_argument("--pe", default="input/editor.exe")
    ap.add_argument("--json", dest="json_out", default=None,
                    help="write machine-readable result under the workspace")
    ap.add_argument("command", choices=["func", "thunk", "ptr", "str", "refs", "iat"])
    ap.add_argument("args", nargs="*")
    ns = ap.parse_args()
    path = Path(ns.pe)
    if not path.is_absolute():
        path = ROOT / path
    if not path.is_file():
        print(f"error: PE not found: {path}", file=sys.stderr)
        return 2
    pe = PE(path)
    print(f"{path.name}: {len(pe.data)} bytes, base {pe.base:#x}, "
          f"{len(pe.sections)} sections, {len(pe.unwind)} unwind records", flush=True)
    args_json = None
    if ns.json_out:
        out = (ROOT / ns.json_out).resolve()
        if not out.is_relative_to(ROOT):
            print("error: --json must stay in the workspace", file=sys.stderr)
            return 2
        args_json = str(out)
    handlers = {"func": cmd_func, "thunk": cmd_thunk, "ptr": cmd_ptr,
                "str": cmd_str, "refs": cmd_refs, "iat": cmd_iat}
    return handlers[ns.command](pe, ns.args)


if __name__ == "__main__":
    sys.exit(main())

